input.command:
f=$(grep -rl 'contaminated' ~/.codex/sessions/2026/08/03/ 2>/dev/null | head -1); echo "FILE: $f"; python3 -c "
import json,sys
f='$f'
msgs=[]
for line in open(f):
    try: d=json.loads(line)
    except: continue
    p=d.get('payload',d)
    t=p.get('type','')
    if t in ('message','user_message','agent_message'):
        role=p.get('role') or t
        c=p.get('content') or p.get('message','')
        if isinstance(c,list): c=' '.join(x.get('text','') for x in c if isinstance(x,dict))
        msgs.append((role,str(c)[:600]))
for i,(r,c) in enumerate(msgs):
    if 'contaminated' in c:
        for r2,c2 in msgs[max(0,i-2):i+3]:
            print('---',r2,':',c2[:500])
        break
"
